import os
import requests

class SafetyClient:
    def __init__(self, api_key: str = None, api_endpoint: str = None):
        self.api_key = api_key if api_key else os.getenv("TEXT_CONTENT_SAFETY_API_KEY")
        self.api_endpoint = api_endpoint if api_endpoint else os.getenv("TEXT_CONTENT_SAFETY_API_ENDPOINT", "https://api.safety.example.com/v1/moderate")

        if not self.api_key:
            raise ValueError("API Key not provided and TEXT_CONTENT_SAFETY_API_KEY environment variable not set.")
        if not self.api_endpoint:
            raise ValueError("API Endpoint not provided and TEXT_CONTENT_SAFETY_API_ENDPOINT environment variable not set.")

    def moderate_text(self, text: str):
        headers = {
            "Content-Type": "application/json",
            "X-API-Key": self.api_key
        }
        payload = {
            "text": text
        }
        try:
            response = requests.post(self.api_endpoint, headers=headers, json=payload)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error during moderation request: {e}")
            raise

import requests
import json
import os

def moderate_batch_messages(messages: list[str]) -> list[dict]:
    """
    Moderates a batch of user messages using Google's Perspective API
    and returns per-message decisions.
    """
    api_key = os.environ.get("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("PERSPECTIVE_API_KEY environment variable not set.")

    api_url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    decisions = []

    for message in messages:
        payload = {
            "comment": {
                "text": message
            },
            "requestedAttributes": {
                "TOXICITY": {},
                "PROFANITY": {},
                "FLIRTATION": {}
            },
            "languages": ["en"]
        }

        headers = {
            "Content-Type": "application/json"
        }

        params = {
            "key": api_key
        }

        try:
            response = requests.post(api_url, headers=headers, params=params, data=json.dumps(payload))
            response.raise_for_status()
            result = response.json()
            decisions.append({
                "message": message,
                "moderation_scores": result.get("attributeScores", {})
            })
        except requests.exceptions.RequestException as e:
            decisions.append({
                "message": message,
                "error": str(e),
                "moderation_scores": {}
            })
    return decisions
